class IncorrectBtsId(Exception):
    """ Raised when ClassicalBts from taf.config.testline.gnb has no declared global_bts_id or instance_id attribute"""


class CouldNotFindBtsType(Exception):
    """ Raised when there is no gnbs nor enbs objects."""


class ConnectionsListNotDefined(Exception):
    """ Raised when there is no list or no one element list assigned to `connections` attribute."""


class EnbConnectionsNotInstanceRealEnb(Exception):
    """ Raised when RealEnb instance is not assigned to `connections` attribute."""


class EnbSystemModuleNotFound(Exception):
    """ Raised when ClassicalBts from taf.config.testline.enb has no declared `system_module` attribute."""


class EnbSystemModuleNotAirscaleInstance(Exception):
    """ Raised when `system_module` attribute has no Airscale instance assigned."""


class EnbSmodNotAList(Exception):
    """ Raised when enb system module is not list or one element list."""


class EnbSmodNotCommonUnitInstance(Exception):
    """ Raised when enb system module is not CommonUnit instance."""


class EnbRMSNotFound(Exception):
    """ Raised when ClassicalBts from taf.config.testline.enb has no declared `rms` attribute."""


class NoMplaneEnbAddressFound(Exception):
    """ Raised when RealEnb from taf.config.testline has no declared `m_plane` attribute if tl.ues attribute is present
     (needed for l3call tests) """


class CapacityUnitsNotFound(Exception):
    """ Raised when there is no baseband modules plugged into `capacity_units` list of system module's representation
     in testline configuration file"""


class NoTestPcConnected(Exception):
    """ Raised when there is no `connections` attribute in test pc's representation in testline
    configuration file """


class SmodNotConnectedToPdu(Exception):
    """ Raised when there `pdu_port` attribute is not defined (None) inside system module's representation in testline
    configuration file """


class CapacityUnitAddrNotFound(Exception):
    """ Raised when there is no `addr` attribute in baseband modules's representation of testline configuration
    file """


class CapacityUnitsRusNotFound(Exception):
    """ Raised when there is no `rus` attribute in baseband modules of GNB BTS Type although lmi board's where
    connected to all RUs (non-empty `rus` attribute is mandatory for all BBMODs in testline configuration file
    while collecting logs """


class NoGnbRusDetected(Exception):
    """ Raised when there are no defined radio units inside GNB's DU object """


class NotUniqueRuPduPortDetected(Exception):
    """ Raised when any of RU's pdu port defined in RU object will be duplicated in any of RU contained in RUs list """


class NoPduPortDefiniedForRu(Exception):
    """ Raised when there is no definied PDU port for Radio unit's representation in testline configuration file """


class NoPdusDetected(Exception):
    """ Raised when tl.pdus list is empty """


class AtenModelAttributeError(Exception):
    """ Raised when ATEN PDU has defined `model` attribute which results in hard-to-find bug on production """


class SmodHwTypeNotDefined(Exception):
    """ Raised when smod's hardware_type parameter is not set """


class BBmodHwTypeNotDefined(Exception):
    """ Raised when bbmod's hardware_type parameter is not set """


class IncorrectNrBtsId(Exception):
    """ Raised when GNB `instance_id` is greater than number of testline's GNBs """


class RadioTypeNotConfigured(Exception):
    """ Raised when RU radio_type parameter is not set """


class SmodSerialNumberNotDefined(Exception):
    """ Raised when SMOD's serial_number is not set """


class BBmodSerialNumberNotDefined(Exception):
    """ Raised when BBMOD's serial_number is not set """


class RmodSerialNumberNotDefined(Exception):
    """ Raised when RMOD's serial_number is not set """


class EnbNotConfigured(Exception):
    """ Raised when _ENB is in line's topology but ENB object is None """


class CoreUnitNotEmptyCapacityUnits(Exception):
    """ Raised when system module is Core Unit and `capacity_units` is not empty list """


class SecondConfigGnbNotInDefaultConfig(Exception):
    """ Raised when GNB of second config could not be found in default config """
    pass


class SecondConfigEnbNotInDefaultConfig(Exception):
    """ Raised when ENB of second config could not be found in default config """
    pass


class SecondConfigTestPcAddrNotFound(Exception):
    """ Raised when test pc addr of second config could not be found in default config """
    pass


class SecondConfigSmodNotFound(Exception):
    """ Raised when smod of second config could not be found in default config """
    pass


class SecondConfigBbmodNotFound(Exception):
    """ Raised when bbmod of second config could not be found in default config """
    pass


class SecondConfigRmodNotFound(Exception):
    """ Raised when rmod of second config could not be found in default config """
    pass
